<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify a certificate — Starmax</title><style>*{box-sizing:border-box}body{margin:0;display:grid;min-height:100vh;place-items:center;padding:24px;background:#0d1422;color:#172033;font-family:Arial,sans-serif}.panel{width:min(580px,100%);padding:38px;border-radius:18px;background:#fff;box-shadow:0 24px 70px #0005}.brand{font-weight:900;letter-spacing:.2em}.brand span{color:#c58b25}h1{margin:28px 0 8px;font-family:Georgia,serif;font-size:36px}p{color:#647083;line-height:1.6}form{display:flex;gap:8px;margin:25px 0}input{min-width:0;flex:1;padding:13px;border:1px solid #cbd5e1;border-radius:8px;text-transform:uppercase}button,.view{padding:13px 18px;border:0;border-radius:8px;color:white;background:#172033;text-decoration:none;font-weight:700}.result{margin-top:25px;padding:22px;border-radius:12px;background:#f6f8fa}.valid{border-left:5px solid #15803d}.revoked,.missing{border-left:5px solid #b91c1c}.result b{display:block;margin-bottom:8px;font-size:19px}.meta{margin:14px 0 20px;color:#475569;font-size:14px;line-height:1.7}</style></head><body><main class="panel"><div class="brand">STARMAX<span>.</span></div><h1>Certificate verification</h1><p>Enter the certificate ID exactly as shown on the document.</p><form><input name="code" value="{{ $code }}" placeholder="SMX-XXXX-XXXX" required><button>Verify</button></form>
